                            managementSensitiveControlsLocked ->
                                "已由管理后台接管，只能从管理后台修改。"
                            !settings.websiteSyncEnabled ->
                                "需要先开启与服务端同步，QQ Bot 才能读取队列、修改玩家资料和发送通知。"
                            settings.oneBotSyncEnabled ->
                                "允许 QQ Bot 读取队列、修改玩家资料，并发送与玩家有关的通知。"
                            else ->
                                "QQ Bot 无法读取队列或修改资料，也不会补发关闭期间产生的通知。"
                        },
                        checked = settings.websiteSyncEnabled && settings.oneBotSyncEnabled,
                        enabled = settings.websiteSyncEnabled && !managementSensitiveControlsLocked,
                        onCheckedChange = {
                            updateDraft(settings.copy(oneBotSyncEnabled = it))
                        }
                    )
                }
            }
            if (visibleSection == QueueSettingsSection.BUSINESS_HOURS) {
            Column(
                Modifier.fillMaxWidth().clip(RoundedCornerShape(CardRadius)).background(CardBackground)
                    .border(1.dp, Separator.copy(alpha = .82f), RoundedCornerShape(CardRadius))
            ) {
                if (managementSensitiveControlsLocked) {
                    Text(
                        managementSensitiveSettingsLockReason,
                        color = WarningText,
                        fontSize = 11.sp,
