                    title = "设置营业时间",
                    description = if (managementSensitiveControlsLocked) {
                        managementSensitiveSettingsLockReason
                    } else if (settings.businessHours.enabled) {
                        businessHoursOwnership +
                            "闭店后停止接收新登记，并为现有队列保留最多 20 分钟的收尾时间；到开店时间时，登记排队不会自动重新开启。"
                    } else {
                        businessHoursOwnership + "不开启时，登记排队不会受到营业时间影响。"
                    },
                    checked = settings.businessHours.enabled,
                    enabled = !managementSensitiveControlsLocked,
                    onCheckedChange = {
                        updateDraft(
                            settings.copy(
                                businessHours = settings.businessHours.copy(enabled = it)
                            )
                        )
                    }
                )
                if (settings.businessHours.enabled) {
                    HorizontalDivider(color = Separator.copy(alpha = .72f))
                    Column(Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 14.dp)) {
                        Text("默认营业时间", color = PrimaryText, fontSize = 14.sp, fontWeight = FontWeight.Medium)
                        Spacer(Modifier.height(8.dp))
                        BusinessHoursTimeRow(
                            hours = settings.businessHours.defaultHours,
                            enabled = !managementSensitiveControlsLocked,
                            disabledReason = managementSensitiveSettingsLockReason,
                            onOpeningClick = {
                                showBusinessTimePicker(context, settings.businessHours.defaultHours.openingMinutes) { minutes ->
                                    updateDraft(
                                        settings.copy(
                                            businessHours = settings.businessHours.copy(
                                                defaultHours = settings.businessHours.defaultHours.copy(
                                                    openingMinutes = minutes
                                                )
                                            )
                                        )
                                    )
                                }
                            },
                            onClosingClick = {
                                showBusinessTimePicker(context, settings.businessHours.defaultHours.closingMinutes) { minutes ->
                                    updateDraft(
                                        settings.copy(
                                            businessHours = settings.businessHours.copy(
                                                defaultHours = settings.businessHours.defaultHours.copy(
                                                    closingMinutes = minutes
                                                )
                                            )
                                        )
                                    )
                                }
                            }
                        )
                        Spacer(Modifier.height(7.dp))
                        Text(
                            "闭店时间早于开店时间时，按次日闭店计算；两者相同时按全天营业计算。",
                            color = TertiaryText,
                            fontSize = 11.sp,
                            lineHeight = 16.sp
                        )
                    }
                    HorizontalDivider(color = Separator.copy(alpha = .72f))
                    QueueRuleSettingRow(
                        title = "按星期分别设置",
                        description = if (managementSensitiveControlsLocked) {
                            managementSensitiveSettingsLockReason
                        } else {
                            "为周一至周日分别指定开店和闭店时间。"
                        },
                        checked = settings.businessHours.useWeeklySchedule,
                        enabled = !managementSensitiveControlsLocked,
                        onCheckedChange = {
                            updateDraft(
                                settings.copy(
                                    businessHours = settings.businessHours.copy(useWeeklySchedule = it)
                                )
                            )
                        }
                    )
                    if (settings.businessHours.useWeeklySchedule) {
                        Column(
                            Modifier.fillMaxWidth().padding(start = 16.dp, end = 16.dp, bottom = 12.dp),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            DayOfWeek.entries.forEach { day ->
                                val hours = settings.businessHours.hoursFor(day)
                                Row(
                                    Modifier.fillMaxWidth(),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        businessDayLabel(day),
                                        color = PrimaryText,
                                        fontSize = 14.sp,
                                        modifier = Modifier.width(58.dp)
                                    )
                                    BusinessTimeButton(
                                        label = "开店 ${formatBusinessTime(hours.openingMinutes)}",
                                        enabled = !managementSensitiveControlsLocked,
                                        disabledReason = managementSensitiveSettingsLockReason,
                                        onClick = {
                                            showBusinessTimePicker(context, hours.openingMinutes) { minutes ->
                                                updateDraft(
                                                    settings.copy(
                                                        businessHours = settings.businessHours.copy(
                                                            weeklyHours = settings.businessHours.weeklyHours +
                                                                (day to hours.copy(openingMinutes = minutes))
                                                        )
                                                    )
                                                )
                                            }
                                        },
                                        modifier = Modifier.weight(1f)
                                    )
                                    Spacer(Modifier.width(8.dp))
                                    BusinessTimeButton(
                                        label = "闭店 ${formatBusinessTime(hours.closingMinutes)}",
                                        enabled = !managementSensitiveControlsLocked,
                                        disabledReason = managementSensitiveSettingsLockReason,
                                        onClick = {
                                            showBusinessTimePicker(context, hours.closingMinutes) { minutes ->
                                                updateDraft(
                                                    settings.copy(
                                                        businessHours = settings.businessHours.copy(
                                                            weeklyHours = settings.businessHours.weeklyHours +
                                                                (day to hours.copy(closingMinutes = minutes))
                                                        )
                                                    )
                                                )
                                            }
                                        },
                                        modifier = Modifier.weight(1f)
                                    )
                                }
                            }
                        }
                    }
                }
            }
            }
            if (visibleSection == QueueSettingsSection.QUEUE_RULES) {
            Column(
                Modifier.fillMaxWidth().clip(RoundedCornerShape(CardRadius)).background(CardBackground)
                    .border(1.dp, Separator.copy(alpha = .82f), RoundedCornerShape(CardRadius))
            ) {
                if (managementSensitiveControlsLocked) {
                    Text(
                        "暂缓一次、暂时离开等终端敏感策略已由管理后台接管，只能从管理后台修改；终端仍可拖动调整等待顺序。",
                        color = WarningText,
                        fontSize = 11.sp,
                        lineHeight = 16.sp,
                        modifier = Modifier.padding(horizontal = 16.dp, vertical = 12.dp)
                    )
                    HorizontalDivider(color = Separator.copy(alpha = .72f))
                }
                QueueRuleSettingRow(
                    title = "允许暂缓一次",
                    description = if (managementSensitiveControlsLocked) {
                        "已由管理后台接管，只能从管理后台修改。"
                    } else {
                        "允许玩家跳过一次游玩机会，并保留当前等待顺序。"
                    },
                    checked = settings.allowDeferOneRound,
                    enabled = !managementSensitiveControlsLocked,
                    onCheckedChange = {
                        updateDraft(settings.copy(allowDeferOneRound = it))
                    }
                )
                HorizontalDivider(color = Separator.copy(alpha = .72f))
                QueueRuleSettingRow(
                    title = "允许暂时离开",
                    description = if (managementSensitiveControlsLocked) {
                        "已由管理后台接管，只能从管理后台修改。"
                    } else {
                        "允许玩家暂时离开现场。暂时离开的登记每次轮到时移至队尾，直到玩家手动取消暂时离开；第 4 次轮到时，系统会将其移除。"
                    },
                    checked = settings.allowTemporaryLeave,
                    enabled = !managementSensitiveControlsLocked,
                    onCheckedChange = {
                        updateDraft(settings.copy(allowTemporaryLeave = it))
                    }
                )
                HorizontalDivider(color = Separator.copy(alpha = .72f))
                QueueRuleSettingRow(
                    title = "显示共同游玩预览",
                    description = "在开放单人位置中显示按当前轮换规则预计的共同游玩玩家。预览不会改变真实队列。",
                    checked = settings.showCommonPlayPreview,
                    onCheckedChange = {
                        updateDraft(settings.copy(showCommonPlayPreview = it))
                    }
                )
                HorizontalDivider(color = Separator.copy(alpha = .72f))
                PairedMachineQueueSettings(
                    settings = settings,
                    locked = managementSensitiveControlsLocked,
                    onSettingsChange = { updated -> updateDraft(updated) },
                    onAddPair = { addingMachinePair = true }
                )
            }
            }
            if (visibleSection == QueueSettingsSection.MACHINES_AND_GROUPS) {
            MachineGroupTable(
                settings = settings,
                enabled = !managementSensitiveControlsLocked,
                disabledReason = managementSensitiveSettingsLockReason,
                onSettingsChange = ::updateDraft
            )
            Spacer(Modifier.height(QueueSpacing.M))
            Column(
                Modifier.fillMaxWidth().clip(RoundedCornerShape(CardRadius)).background(CardBackground)
                    .border(1.dp, Separator.copy(alpha = .82f), RoundedCornerShape(CardRadius))
            ) {
                Column(Modifier.fillMaxWidth().padding(16.dp)) {
                Text("机台", color = PrimaryText, fontSize = QueueTextSize.CardTitle, fontWeight = FontWeight.SemiBold)
                Spacer(Modifier.height(6.dp))
                if (managementSensitiveControlsLocked) {
                    Text(
                        managementSensitiveSettingsLockReason,
                        color = WarningText,
                        fontSize = 11.sp,
                        lineHeight = 16.sp
                    )
                    Spacer(Modifier.height(8.dp))
                }
                Text(
                    "按现场实际情况添加或删除机台。机台编号始终从 A 开始连续排列，最多支持到 J。",
                    color = SecondaryText,
                    fontSize = 11.sp,
                    lineHeight = 16.sp
                )
                if (registrationOpen) {
                    Spacer(Modifier.height(8.dp))
                    Text(
                        "关闭登记排队后才能添加、删除机台、修改游玩容量或计划游玩时间。分组、备注与机台详情仍可直接更新。",
                        color = WarningText,
                        fontSize = 11.sp,
                        lineHeight = 16.sp
                    )
                }
                Spacer(Modifier.height(12.dp))
                val activeMachineId = selectedMachineConfigurationId.takeIf {
                    it in settings.configuredMachineIds
                } ?: settings.configuredMachineIds.first()
                MachineRosterSelector(
                    machineIds = settings.configuredMachineIds,
                    selectedMachineId = activeMachineId,
                    canAdd = !managementSensitiveControlsLocked && !registrationOpen &&
                        settings.configuredMachineCount < MachineId.entries.size,
                    canDelete = !managementSensitiveControlsLocked && !registrationOpen &&
                        settings.configuredMachineCount > 1,
                    structureDisabledReason = when {
                        managementSensitiveControlsLocked -> managementSensitiveSettingsLockReason
                        registrationOpen ->
                        "请先关闭登记排队，再修改机台数量。"
                        else -> "最多支持 10 台机台。"
                    },
                    onSelect = { selectedMachineConfigurationId = it },
                    onAdd = {
                        appendMachineConfiguration(
                            settings,
                            settings.machineGroupId(activeMachineId)
                        )?.let { updated ->
                            updateDraft(updated)
                            selectedMachineConfigurationId = updated.configuredMachineIds.last()
                        }
                    },
                    onDelete = { machineDeletionTarget = activeMachineId }
                )
                Spacer(Modifier.height(18.dp))
                MachineConfigurationEditor(
                    machineId = activeMachineId,
                    configuration = settings.machineConfiguration(activeMachineId),
                    editable = !managementSensitiveControlsLocked,
                    behaviorEditable = !registrationOpen && !managementSensitiveControlsLocked,
                    disabledReason = managementSensitiveSettingsLockReason,
                    onConfigurationChange = { updated ->
                        updateDraft(
                            settings.copy(
                                machineConfigurations = settings.machineConfigurations +
                                    (activeMachineId to updated)
                            )
                        )
                    }
                )
                }
            }
            }
                }
            }
        }
        Spacer(Modifier.height(14.dp))
        Row(
            Modifier.fillMaxWidth()
                .widthIn(max = terminalContentMaxWidth(1160.dp, horizontalPadding = 64.dp))
                .align(Alignment.CenterHorizontally),
            verticalAlignment = Alignment.CenterVertically
        ) {
            val validationMessage = when {
                !installationNamesValid -> "请填写有效的机厅名称和终端名称。"
                !remarksValid -> "请填写所有机台的备注。"
                !machineDetailsValid -> "请填写选择为“其他”的游戏类型或服务器名称。"
                !machineGroupsValid -> "请填写所有机台分组的名称。"
                !connectionChangeValid -> "请填写有效的服务器地址和终端同步令牌。"
                !settings.websiteSyncEnabled || queueConnectionConfigured -> null
                else -> "开启与服务端同步前，请先填写有效的服务器连接。"
            }
            if (validationMessage != null && settingsChanged) {
                Text(
                    validationMessage,
                    color = Destructive,
                    fontSize = 11.sp,
                    lineHeight = 16.sp,
                    modifier = Modifier.weight(1f).padding(end = 16.dp)
                )
            } else {
                Text(
                    if (settingsChanged) "切换分类不会丢失本次修改。" else "切换分类不会立即修改运行中的设置。",
                    color = TertiaryText,
                    fontSize = 11.sp,
                    modifier = Modifier.weight(1f).padding(end = 16.dp)
                )
            }
            PrimaryButton(
                text = "保存设置",
                onClick = {
                    val queueSettingsSaved = !queueSettingsChanged ||
                        onSettingsChange(settingsToSave)
                    val installationNamesSaved = queueSettingsSaved &&
                        (!installationNamesChanged || onInstallationNamesChange(
                            normalizedVenueNameDraft,
                            normalizedTerminalNameDraft
                        ))
                    if (queueSettingsSaved && installationNamesSaved) {
                        Toast.makeText(
                            context,
                            panguSpacing("应用设置已保存。"),
                            Toast.LENGTH_SHORT
                        ).show()
                        onBack()
                    } else if (queueSettingsSaved) {
                        Toast.makeText(
                            context,
                            panguSpacing("应用设置已保存；机厅与终端名称未能写入本机，请重试。"),
                            Toast.LENGTH_LONG
                        ).show()
                    }
                },
                modifier = Modifier.width(220.dp),
                enabled = settingsChanged && settingsValid,
                disabledReason = when {
                    !settingsChanged -> "当前没有未保存的设置。"
                    !installationNamesValid -> "请填写有效的机厅名称和终端名称。"
                    !remarksValid -> "请填写所有已启用机台的备注。"
                    !machineDetailsValid -> "请填写选择为“其他”的机台类型或服务器名称。"
                    !machineGroupsValid -> "请填写所有机台分组的名称。"
                    !connectionChangeValid -> "请填写有效的服务器地址和终端同步令牌。"
                    else -> "开启与服务端同步前，请先填写有效的服务器连接。"
                }
            )
        }
    }
    if (showTakeoverConfirmation) {
        RemoveRegistrationConfirmation(
            title = "接管同步身份？",
            message = "接管后，网站和 QQ Bot 将以本机队列作为正式数据。请仅在确实需要用本机替代当前同步终端时继续。",
            confirmText = "确认接管",
            onDismiss = { showTakeoverConfirmation = false },
            onConfirm = {
                updateDraft(settings.copy(syncMode = QueueSyncMode.TAKEOVER))
                showTakeoverConfirmation = false
            }
        )
    }
    machineDeletionTarget?.let { target ->
        val configuredIds = settings.configuredMachineIds
        val targetIndex = configuredIds.indexOf(target)
        val reindexedIds = configuredIds.drop(targetIndex + 1)
        RemoveRegistrationConfirmation(
            title = "删除 ${machineName(target, settings.machineRemark(target))}？",
            message = buildString {
                append("这台机台将从当前配置中移除。")
                if (reindexedIds.isNotEmpty()) {
                    append("删除后，")
                    append(
                        reindexedIds.joinToString("、") { machineId ->
                            "原机台 ${machineId.name} 改为 机台 ${MachineId.entries[machineId.ordinal - 1].name}"
                        }
                    )
                    append("。机台详情、分组和运行状态会一同移动。")
                }
                append("本次修改仍需点击“保存设置”后才会生效。")
            },
            confirmText = "删除机台",
            onDismiss = { machineDeletionTarget = null },
            onConfirm = {
                removeMachineConfiguration(settings, target)?.let { updated ->
                    updateDraft(updated)
                    selectedMachineConfigurationId = updated.configuredMachineIds[
                        targetIndex.coerceAtMost(updated.configuredMachineIds.lastIndex)
                    ]
                }
                machineDeletionTarget = null
            }
        )
    }
    if (addingMachinePair) {
        AddMachinePairDialogs(
            settings = settings,
            onSettingsChange = { updated -> updateDraft(updated) },
            onDismiss = { addingMachinePair = false }
        )
    }
    if (showDiscardConfirmation) {
        RemoveRegistrationConfirmation(
            title = "放弃未保存的设置？",
            message = "返回后，这次对机厅与终端名称、营业时间、同步设置、排队规则和机台配置所做的修改不会生效。",
            confirmText = "放弃修改",
            onDismiss = { showDiscardConfirmation = false },
            onConfirm = {
                showDiscardConfirmation = false
                onBack()
            }
        )
    }
    if (showVenueRebindConfirmation) {
        RemoveRegistrationConfirmation(
            title = "重新绑定当前服务器？",
            message = "确认后，终端会放弃原有的机厅 ID，并在当前服务器上重新注册本终端所属的机厅。核对成功后，本机现有队列和玩家资料会同步到服务端；本机的队列、玩家资料和历史记录不会被清除。请仅在已经核对服务器地址与现场归属后继续。",
            confirmText = "确认重新绑定",
            onDismiss = { showVenueRebindConfirmation = false },
            onConfirm = {
                if (onRebindInstallation()) showVenueRebindConfirmation = false
            }
        )
    }
}

@Composable
private fun TerminalStartupCheckScreen() {
    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
        Column(horizontalAlignment = Alignment.CenterHorizontally) {
            CircularProgressIndicator(
                modifier = Modifier.size(32.dp),
                color = SystemBlue,
                strokeWidth = 3.dp
            )
            Spacer(Modifier.height(14.dp))
            Text(
                "正在核对本机数据",
                color = PrimaryText,
                fontSize = 17.sp,
                fontWeight = FontWeight.SemiBold
            )
            Spacer(Modifier.height(5.dp))
