            imageVector = if (increase) Icons.Default.Add else MinusIcon,
            contentDescription = if (increase) "增加" else "减少",
            tint = if (enabled) SystemBlue else TertiaryText,
            modifier = Modifier.size(22.dp)
        )
    }
}

